// Queen Slime -------------------------------------------------------------------------------
class QueenSlime extends BossBase {
  constructor(x, y) { super(x, y, 100, 80, 'queen_slime'); this.flying = false; this.jumpTimer = 50; this.squash = 0; this.setState('hop'); }
  ai(world, p, game) {
    const p2 = this.hp < this.maxHp * 0.5;
    if (p2 && this.state === 'hop') { this.setState('fly'); game.message('Queen Slime takes to the air!', '#e080ff'); }
    if (this.state === 'hop' || this.state === 'start') {
      this.updateLiquidState(world); if (this.onGround) { this.vx *= 0.8; if (--this.jumpTimer <= 0) { this.dir = p.cx > this.cx ? 1 : -1; const big = Math.random() < 0.4; this.vx = this.dir * (big ? 6 : 3.5); this.vy = big ? -13 : -9; this.jumpTimer = randInt(30, 60); Audio_.play('slime'); if (Math.random() < 0.5) this.spawnMinion(game, choose(['crystal_slime', 'bouncy_slime', 'heavenly_slime']), this.cx + rand(-40, 40), this.y); } }
      this.applyGravity(); this.moveAndCollide(world); if (this.collidedX && this.onGround) this.vy = -10; this.squash = lerp(this.squash, this.onGround ? 0.2 : -0.2, 0.25);
    } else { this.hoverTo(p.cx + Math.sin(this.t * 0.03) * 200, p.y - 180, 5); if (this.st % 40 === 0) { for (let k = -2; k <= 2; k++) { const b = Gensokyo.bullet(game, this.cx + k * 20, this.cy + 30, k * 1.2, 5, { owner: this, color: '#e080ff', hi: '#fff', damage: Math.round(this.damage * 0.6), sourceName: "Queen Slime's crystal", size: 6, life: 150 }); b.ghost = false; b.gravity = 0.05; } } if (this.st % 150 === 0) { this.chargeAt(p, 12); this.setState('fly'); } this.vx *= 0.96; this.vy *= 0.96; }
    if (Math.abs(this.cx - p.cx) > 60 * TILE) { this.x = p.cx - 200; this.y = p.y - 200; }
  }
  draw(ctx, camX, camY) { const sx = 1 + this.squash, sy = 1 - this.squash; const w = this.w * sx, h = this.h * sy; const x = snap(this.cx - camX - w / 2), y = snap(this.y + this.h - camY - h); ctx.globalAlpha = this.hitFlash > 0 ? 0.6 : 0.85; ctx.fillStyle = 'rgba(230,120,255,1)'; roundRect(ctx, x, y, Math.round(w), Math.round(h), 24); ctx.fill(); ctx.fillStyle = 'rgba(255,255,255,0.35)'; roundRect(ctx, x + w * 0.15, y + h * 0.12, w * 0.3, h * 0.25, 8); ctx.fill(); ctx.globalAlpha = 1; ctx.fillStyle = '#ffd040'; const cw = w * 0.35, cx0 = x + w / 2 - cw / 2, cy0 = y - 16; ctx.beginPath(); ctx.moveTo(cx0, cy0 + 16); ctx.lineTo(cx0, cy0); ctx.lineTo(cx0 + cw * 0.25, cy0 + 8); ctx.lineTo(cx0 + cw * 0.5, cy0 - 4); ctx.lineTo(cx0 + cw * 0.75, cy0 + 8); ctx.lineTo(cx0 + cw, cy0); ctx.lineTo(cx0 + cw, cy0 + 16); ctx.fill(); ctx.fillStyle = '#c0f0ff'; for (let k = 0; k < 3; k++) { ctx.beginPath(); ctx.moveTo(x + w * (0.25 + k * 0.25), y + h * 0.5); ctx.lineTo(x + w * (0.25 + k * 0.25) + 8, y + h * 0.3); ctx.lineTo(x + w * (0.25 + k * 0.25) + 16, y + h * 0.5); ctx.fill(); } ctx.fillStyle = '#000'; ctx.fillRect(snap(x + w * (this.dir > 0 ? 0.6 : 0.25)), snap(y + h * 0.35), 8, 10); if (this.state === 'fly') { ctx.fillStyle = 'rgba(255,255,255,0.7)'; ctx.beginPath(); ctx.ellipse(x - 10, y + h * 0.4, 30, 10, -0.4, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.ellipse(x + w + 10, y + h * 0.4, 30, 10, 0.4, 0, Math.PI * 2); ctx.fill(); } }
}
