// The Twins ----------------------------------------------------------------------------------
class Twin extends BossBase {
  constructor(x, y, kind) { super(x, y, 90, 90, 'the_twins'); this.kind = kind; this.name = kind === 'ret' ? 'Retinazer' : 'Spazmatism'; this.form = 1; this.setState('hover'); this.hp = this.maxHp = kind === 'ret' ? 20000 : 23000; }
  ai(world, p, game) {
    if (this.form === 1 && this.hp < this.maxHp * 0.5) { this.form = 2; game.message(`${this.name} transforms!`, '#c040c0'); FX.flash('#ffffff', 10, 0.3); this.defense += 10; }
    const ret = this.kind === 'ret';
    if (this.state === 'start' || this.state === 'hover') {
      this.hoverTo(p.cx + (ret ? 0 : (this.cx < p.cx ? -1 : 1) * 260), p.y - (ret ? 260 : 60), ret ? 4 : 5);
      if (ret) { if (this.st % (this.form === 2 ? 12 : 40) === 0) { const b = this.shoot(game, p, { speed: 10, color: '#ff2020', name: 'laser', size: 4, life: 120 }); b.trail = { color: '#ff2020', len: 8, width: 3 }; } }
      else { if (this.form === 1 && this.st % 30 === 0) { const b = this.shoot(game, p, { speed: 7, color: '#80ff40', name: 'cursed flame', size: 6, life: 120 }); b.ghost = false; } if (this.st > (this.form === 2 ? 60 : 120)) this.setState('charge'); }
    } else if (this.state === 'charge') {
      if (this.st === 1) { this.chargeAt(p, this.form === 2 ? 15 : 12); Audio_.play('swing'); }
      this.glide(); if (this.form === 2 && this.st % 4 === 0) { const b = Gensokyo.bullet(game, this.cx, this.cy, this.vx * 0.6 + rand(-2, 2), this.vy * 0.6 + rand(-2, 2), { owner: this, color: '#80ff40', hi: '#fff', damage: Math.round(this.damage * 0.5), sourceName: "Spazmatism's cursed flamethrower", size: 6, life: 40 }); b.ghost = false; }
      if (this.st > 45) { this.charges = (this.charges || 0) + 1; this.setState(this.charges % 3 === 0 ? 'hover' : 'charge'); }
    }
    this.dir = p.cx < this.cx ? -1 : 1;
    if (this.sibling && this.sibling.dead && this.t % 300 === 0) game.addDamageText(this.cx, this.y, 'enraged', '#ff4040');
  }
  die(game) { const other = this.sibling; super.die(game); if (other && !other.dead) { game.boss = other; game.message(`${this.name} has been defeated! ${other.name} remains.`, '#ffe75a'); game.world.bossesDefeated.the_twins = false; } }
  draw(ctx, camX, camY) { const x = snap(this.cx - camX), y = snap(this.cy - camY); ctx.save(); ctx.translate(x, y); ctx.rotate(Math.atan2(this.vy, this.vx) * 0.2); ctx.globalAlpha = this.hitFlash > 0 ? 0.6 : 1; ctx.fillStyle = this.form === 2 ? '#606068' : '#e8e0e0'; ctx.beginPath(); ctx.ellipse(0, 0, 44, 40, 0, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = '#c03030'; ctx.lineWidth = 2; for (let k = 0; k < 6; k++) { ctx.beginPath(); ctx.moveTo(-30 + k * 12, -30); ctx.lineTo(-24 + k * 12, 10); ctx.stroke(); } ctx.fillStyle = this.kind === 'ret' ? '#ff2020' : '#80ff40'; ctx.beginPath(); ctx.arc(this.dir * 14, 0, 18, 0, Math.PI * 2); ctx.fill(); ctx.fillStyle = '#000'; ctx.beginPath(); ctx.arc(this.dir * 18, 0, 8, 0, Math.PI * 2); ctx.fill(); if (this.form === 2) { ctx.fillStyle = '#404048'; ctx.fillRect(-50, -8, 20, 16); ctx.fillStyle = this.kind === 'ret' ? '#ff6060' : '#a0ff60'; ctx.fillRect(this.dir * 30 - 6, -6, 12, 12); } ctx.restore(); ctx.globalAlpha = 1; }
}
