// Skeletron Prime ---------------------------------------------------------------------------------
class SkeletronPrime extends BossBase {
  constructor(x, y) { super(x, y, 80, 80, 'skeletron_prime'); this.spin = 0; this.setState('hover'); }
  setup(game) {
    const limbs = [['Prime Saw', -110, 40, '#c0c0c8', (l, w, p, g) => {}, 'melee'], ['Prime Vice', 110, 40, '#a0a0a8', null, 'melee'], ['Prime Cannon', -70, -60, '#606068', (l, w, p, g) => { if (l.t % 70 === 0) { const b = Gensokyo.bullet(g, l.cx, l.cy, (p.cx - l.cx) / 60, -8, { owner: l.parent, color: '#ff8020', hi: '#fff', damage: Math.round(l.parent.damage * 0.7), sourceName: "Prime Cannon's grenade", size: 6, life: 150 }); b.ghost = false; b.gravity = 0.18; } }, 'ranged'], ['Prime Laser', 70, -60, '#8080a0', (l, w, p, g) => { if (l.t % 50 === 0) { const dx = p.cx - l.cx, dy = p.cy - l.cy, d = Math.hypot(dx, dy) || 1; const b = Gensokyo.bullet(g, l.cx, l.cy, dx / d * 9, dy / d * 9, { owner: l.parent, color: '#ff40ff', hi: '#fff', damage: Math.round(l.parent.damage * 0.6), sourceName: "Prime Laser's laser", size: 4, life: 120 }); b.trail = { color: '#ff40ff', len: 6, width: 3 }; } }, 'ranged']];
    for (const [name, ox, oy, col, fn, kind] of limbs) { const l = new BossPart(this, 40, 40, { name, hp: 7000, damage: 45, defense: 30, type: 'prime_limb', ai: (l, w, p, g) => { const par = l.parent; if (kind === 'melee' && l.t % 160 > 110) { const dx = p.cx - l.cx, dy = p.cy - l.cy, d = Math.hypot(dx, dy) || 1; l.x += dx / d * 8; l.y += dy / d * 8; } else { l.x = lerp(l.x, par.cx + ox - l.w / 2 + Math.sin(l.t * 0.05) * 8, 0.08); l.y = lerp(l.y, par.cy + oy - l.h / 2, 0.08); } if (fn) fn(l, w, p, g); }, draw: (l, ctx, camX, camY) => { const x = snap(l.cx - camX), y = snap(l.cy - camY); ctx.globalAlpha = l.hitFlash > 0 ? 0.6 : 1; ctx.strokeStyle = '#606068'; ctx.lineWidth = 4; ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(l.parent.cx - camX + Math.sign(ox) * 30, l.parent.cy - camY + Math.sign(oy) * 20); ctx.stroke(); ctx.fillStyle = col; ctx.fillRect(x - 16, y - 16, 32, 32); ctx.fillStyle = '#ff2020'; ctx.fillRect(x - 4, y - 4, 8, 8); if (name === 'Prime Saw') { ctx.strokeStyle = '#e0e0e8'; ctx.lineWidth = 3; ctx.beginPath(); ctx.arc(x, y, 22, l.t * 0.4, l.t * 0.4 + Math.PI * 1.5); ctx.stroke(); } ctx.globalAlpha = 1; } }); game.enemies.push(l); }
  }
  ai(world, p, game) {
    this.defense = this.spin > 0 ? 60 : this.bdef.defense; this.damage = this.spin > 0 ? this.bdef.damage * 2 : this.bdef.damage;
    if (this.spin > 0) { this.spin--; this.chargeAt(p, game.expert ? 7 : 5.5); this.glide(); if (this.spin === 0) this.setState('hover'); return; }
    this.hoverTo(p.cx, p.y - 200, 4);
    if (this.st > 360) { this.spin = 180; this.setState('spin'); Audio_.play('zombie'); FX.shake(3, 10); }
  }
  draw(ctx, camX, camY) { const x = snap(this.cx - camX), y = snap(this.cy - camY); ctx.save(); ctx.translate(x, y); if (this.spin > 0) ctx.rotate(this.t * 0.35); ctx.globalAlpha = this.hitFlash > 0 ? 0.6 : 1; ctx.fillStyle = '#707078'; ctx.fillRect(-34, -38, 68, 56); ctx.fillStyle = '#505058'; ctx.fillRect(-24, 18, 48, 16); ctx.fillStyle = '#101018'; ctx.fillRect(-24, -24, 18, 18); ctx.fillRect(6, -24, 18, 18); ctx.fillStyle = '#ff2020'; ctx.fillRect(-19, -19, 8, 8); ctx.fillRect(11, -19, 8, 8); ctx.fillStyle = '#c0c0c8'; for (let k = 0; k < 5; k++) ctx.fillRect(-22 + k * 10, 20, 5, 10); ctx.fillStyle = '#404048'; ctx.fillRect(-40, -44, 80, 6); ctx.restore(); ctx.globalAlpha = 1; }
}
